create extension if not exists pgcrypto;
create table if not exists public.customers (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, name text not null, phone text, status text not null default 'مهتم', next_follow_up date, source text, request text, address text, note text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.orders (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, customer_id uuid not null references public.customers(id) on delete cascade, product text not null, total numeric(12,2) not null default 0, deposit numeric(12,2) not null default 0, status text not null default 'جديد', delivery_date date, reminder_days integer default 1, source text, size text, fabric text, note text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.follow_ups (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, customer_id uuid not null references public.customers(id) on delete cascade, followed_at timestamptz not null default now(), result text, note text, next_follow_up date);
alter table public.customers enable row level security; alter table public.orders enable row level security; alter table public.follow_ups enable row level security;
drop policy if exists "customers own rows" on public.customers; create policy "customers own rows" on public.customers for all using (auth.uid()=user_id) with check (auth.uid()=user_id);
drop policy if exists "orders own rows" on public.orders; create policy "orders own rows" on public.orders for all using (auth.uid()=user_id) with check (auth.uid()=user_id);
drop policy if exists "followups own rows" on public.follow_ups; create policy "followups own rows" on public.follow_ups for all using (auth.uid()=user_id) with check (auth.uid()=user_id);
create or replace function public.set_updated_at() returns trigger language plpgsql as $$ begin new.updated_at=now(); return new; end $$;
drop trigger if exists customers_updated_at on public.customers; create trigger customers_updated_at before update on public.customers for each row execute function public.set_updated_at();
drop trigger if exists orders_updated_at on public.orders; create trigger orders_updated_at before update on public.orders for each row execute function public.set_updated_at();
